13	
14	// The prefix-truncation point lives in its own sidecar
15	// ("truncate.idx"), deliberately separate from the rebuildable
16	// index.idx: index.idx is pure cache and may be deleted at any time,
17	// but the truncation point is the only record that historical
18	// sequences once existed, so deleting index.idx must not turn
19	// ErrTruncated into ErrUnknownBatch.
20	//
21	// Layout, little-endian:
22	//
23	//	magic    6 bytes  "BCLTRN"
24	//	version  2 bytes  uint16
25	//	through  8 bytes  highest sequence reclaimed so far
26	//	segBound 8 bytes  highest segment file number reclaimed so far
27	//	crc32    4 bytes  IEEE checksum of every preceding byte
28	//
29	// The file is replaced atomically (fsynced temp + rename) before any
30	// segment file is removed, so a crash can only leave the previous
31	// marker or the new one, never a torn record. Open completes the file
32	// removal a persisted marker describes, hence a reopen after a crash
33	// mid-truncation sees either the complete old state or the complete
34	// new state.
35	var (
36		truncateMagic   = []byte{'B', 'C', 'L', 'T', 'R', 'N'}
37		truncateVersion = uint16(1)
38	)
39	
40	type truncateMarker struct {
41		through  uint64
42		segBound uint64
43	}
44	
45	const truncateFileLen = 6 + 2 + 8 + 8 + 4
46	
47	func (l *Log) truncatePath() string {
48		return filepath.Join(l.dir, "truncate.idx")
49	}
50	
51	// encodeTruncateMarker serialises a truncation point with its trailing
52	// checksum.
53	func encodeTruncateMarker(m truncateMarker) []byte {
54		buf := make([]byte, 0, truncateFileLen)
55		buf = append(buf, truncateMagic...)
56		var tmp [8]byte
57		binary.LittleEndian.PutUint16(tmp[:2], truncateVersion)
58		buf = append(buf, tmp[:2]...)
59		binary.LittleEndian.PutUint64(tmp[:], m.through)
60		buf = append(buf, tmp[:]...)
61		binary.LittleEndian.PutUint64(tmp[:], m.segBound)
62		buf = append(buf, tmp[:]...)
63		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
64		return append(buf, tmp[:4]...)
65	}
66	
67	// readTruncateMarker loads the truncation point. No marker (the common
68	// case for a log that has never been truncated) reports ok=false. A
69	// present but malformed marker is tampering, like any other framing
70	// inconsistency: ErrCorruptSegment.
71	func (l *Log) readTruncateMarker() (truncateMarker, bool, error) {
72		path := l.truncatePath()
73		data, err := os.ReadFile(path)
74		if os.IsNotExist(err) {
75			return truncateMarker{}, false, nil
76		}
77		if err != nil {
78			return truncateMarker{}, false, err
79		}
80		if len(data) != truncateFileLen ||
81			string(data[:6]) != string(truncateMagic) ||
82			binary.LittleEndian.Uint16(data[6:8]) != truncateVersion {
83			return truncateMarker{}, false, ErrCorruptSegment
84		}
85		stored := binary.LittleEndian.Uint32(data[len(data)-4:])
86		if crc32.ChecksumIEEE(data[:len(data)-4]) != stored {
87			return truncateMarker{}, false, ErrCorruptSegment
88		}
89		// A stale temp file from a crash before the rename never replaces a
90		// good marker; best effort cleanup.
91		_ = os.Remove(path + ".tmp")
92		return truncateMarker{
93			through:  binary.LittleEndian.Uint64(data[8:16]),
94			segBound: binary.LittleEndian.Uint64(data[16:24]),
95		}, true, nil
96	}
97	
98	// writeTruncateMarker durably replaces truncate.idx: the bytes land in
99	// a synced temp file first, then the rename makes the new point
100	// atomic. A lost rename leaves the previous marker in place, so the
101	// operation reads as the old state; syncing the directory is best
102	// effort and never required for correctness because Open converges.
103	func (l *Log) writeTruncateMarker(m truncateMarker) error {
104		path := l.truncatePath()
105		tmp := path + ".tmp"
106		f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
107		if err != nil {
108			return err
109		}
110		if _, err := f.Write(encodeTruncateMarker(m)); err != nil {
111			f.Close()
112			os.Remove(tmp)
113			return err
114		}
115		if err := syncFile(f); err != nil {
116			f.Close()
117			os.Remove(tmp)
118			return err
119		}
120		if err := f.Close(); err != nil {
121			os.Remove(tmp)
122			return err
123		}
124		if err := os.Rename(tmp, path); err != nil {
125			os.Remove(tmp)
126			return err
127		}
128		_ = syncDir(l.dir)
129		return nil
130	}
131	
132	// DeleteThrough reclaims the consumed prefix of the log. It removes
133	// whole segment files only: every complete segment whose highest
134	// reserved sequence (its last committed batch or its last hole
135	// marker, whichever is greater) is at or below seq is deleted, and
136	// the number of removed files is returned. Entries are never
137	// rewritten, and a batch or group is never split across the boundary:
138	// when seq falls in the middle of a segment, that segment is
139	// retained and the truncation stops one segment short.
140	//
141	// DeleteThrough(0) changes nothing and returns 0. seq must be a
142	// committed batch; otherwise — seq is unknown, a permanent hole,
143	// still staged, or a staged batch reserves a sequence at or below
144	// seq — DeleteThrough returns ErrInvalidRetention before touching
145	// anything. A call that finds no fully-reclaimable segment also
146	// changes nothing and returns 0.
147	//
148	// The truncation point is persisted (truncate.idx, atomically
149	// replaced) before any segment file is removed, so a crash leaves
150	// either the complete old state or the complete new state: a reopen
151	// finishes any pending file removal, and historical sequences keep
152	// reading as ErrTruncated even when index.idx is rebuilt from
153	// scratch. Idempotency keys that lived in deleted segments are
154	// released and may be reused; keys in retained segments keep their
155	// same-key dedup and different-key ErrBatchIDConflict.
156	func (l *Log) DeleteThrough(seq uint64) (int, error) {
157		l.mu.Lock()
158		defer l.mu.Unlock()
159		if l.closed {
160			return 0, errClosed
161		}
162		if seq == 0 {
163			return 0, nil
164		}
165		if _, ok := l.index[seq]; !ok {
166			// Unknown, a permanent hole, or merely staged: only a sequence
167			// with a committed batch may anchor a truncation.
168			return 0, ErrInvalidRetention
169		}
170		// An uncommitted staged batch at or below seq would be reclaimed
171		// together with the history it is logically still ahead of; its
172		// reservation has to outlive the truncation.
173		for s, recs := range l.staged {
174			if recs != nil && s <= seq {
175				return 0, ErrInvalidRetention
176			}
177		}
178	
179		physical, err := listSegmentNumbers(l.dir)
180		if err != nil {
181			return 0, err
182		}
183		boundOf := make(map[int]uint64, len(l.segs))
184		segByFile := make(map[int]*segInfo, len(l.segs))
185		for i := range l.segs {
186			s := &l.segs[i]
187			bound := uint64(0)
188			if s.hasCommits {
189				bound = s.LastSeq
190			}
191			if s.hasHoles && s.maxHole > bound {
192				bound = s.maxHole
193			}
194			boundOf[s.file] = bound
195			segByFile[s.file] = s
196		}
197		// Segment files absent from l.segs are empty (a torn first entry
198		// truncated to zero); their bound is 0. Take the contiguous prefix
199		// whose every bound is at or below seq — the first segment that
200		// overhangs seq ends the prefix, along with everything after it.
201		var deleted []int
202		for _, n := range physical {
203			if boundOf[n] > seq {
204				break
205			}
206			deleted = append(deleted, n)
207		}
208		if len(deleted) == 0 {
209			return 0, nil
210		}
211		segBound := deleted[len(deleted)-1]
212		retained := physical[len(deleted):]
213	
214		// Consumer protection: the prefix is reclaimable only once every
215		// registered consumer has confirmed past the highest committed batch
216		// in it. Holes reserve no data and do not count. With no consumers at
217		// all the original behavior is unchanged. The check happens before
218		// anything is persisted or removed, so a blocked call leaves files,
219		// the index and idempotency keys byte-for-byte untouched.
220		var highestCommitted uint64
221		for _, n := range deleted {
222			if s, known := segByFile[n]; known && s.hasCommits && s.LastSeq > highestCommitted {
223				highestCommitted = s.LastSeq
224			}
225		}
226		if highestCommitted > 0 {
227			for _, confirmed := range l.consumers {
228				if highestCommitted > confirmed {
229					return 0, ErrRetentionBlocked
230				}
231			}
232		}
233	
234		// 1) Durably commit the truncation point before removing anything.
235		// A failure here leaves the full old state byte-for-byte.
236		if err := l.writeTruncateMarker(truncateMarker{through: seq, segBound: uint64(segBound)}); err != nil {
237			return 0, fmt.Errorf("%w: %v", ErrRetentionFailed, err)
238		}
239	
240		// 2) Close the open current segment when it is being removed.
241		currentDeleted := false
242		for _, n := range deleted {
243			if n == l.segIndex {
244				currentDeleted = true
245				break
246			}
247		}
248		if currentDeleted && l.file != nil {
249			l.file.Close()
250			l.file = nil
251			l.fileSize = 0
252			// The next write opens segBound+1; segment numbers are never
253			// reused, even when every file has been reclaimed. Reset the
254			// write-side counters now so no later path can commit into the
255			// stale segment view.
256			l.segIndex = segBound
257			l.curBatches = 0
258		}
259	
260		// 3) Remove the old segment files. The marker already owns the
261		// outcome: a failure converges on reopen, so keep going to reach
262		// the complete new state in this process too.
263		var firstErr error
264		for _, n := range deleted {
265			if err := removeFile(l.segmentPath(n)); err != nil && !os.IsNotExist(err) && firstErr == nil {
266				firstErr = err
267			}
268		}
269		// Removed files no longer need a durability barrier; a still-open
270		// future writer only ever touches the retained segments.
271		for _, n := range deleted {
272			delete(l.segDirty, n)
273		}
274		_ = syncDir(l.dir)
275	
276		// 4) Rebuild the in-memory view from exactly the retained files,
277		// preserving live staged batches (all of which reserve sequences
278		// above seq, checked above) and their keys. Scanning also recovers
279		// a torn tail of the last retained segment as usual.
280		live := make(map[uint64][][]byte)
281		liveIDs := make(map[uint64]string)
282		for s, recs := range l.staged {
283			if recs != nil {
284				live[s] = recs
285				if id := l.stagedID[s]; id != "" {
286					liveIDs[s] = id
287				}
288			}
289		}
290		// Retained batches keep their original publication generations, so
291		// a Scan snapshot taken before the truncation keeps seeing exactly
292		// the retained batches it could already see (their files survive),
293		// while every post-truncation commit lands above oldGen and stays
294		// invisible to it — the same snapshot guarantee as always.
295		oldGen := l.gen
296		oldGenBySeq := make(map[uint64]uint64, len(l.index))
297		for s, ref := range l.index {
298			oldGenBySeq[s] = ref.gen
299		}
300		p, scanErr := l.scanSegments(retained)
301		if scanErr != nil {
302			// The retained files are unreadable: do not adopt a partial
303			// view. The old state is already partly deleted on disk, but the
304			// durable marker makes the outcome converge on the next open;
305			// surface the failure and leave index state untouched.
306			return len(deleted), fmt.Errorf("%w: %v", ErrRetentionFailed, scanErr)
307		}
308		l.index = make(map[uint64]entryRef)
309		l.ids = make(map[string]uint64)
310		l.staged = make(map[uint64][][]byte)
311		l.stagedID = make(map[uint64]string)
312		l.segs = nil
313		l.gen = 0
314		l.nextSeq = 1
315		l.through = seq
316		if err := l.installSnapshot(p, retained); err != nil && firstErr == nil {
317			firstErr = err
318		}
319		// Rebuilt view: the deleted files already dropped out above; the
320		// retained committed segments may still hold bytes that no fsync has
321		// covered (Sync:false), so the next checkpoint must barrier them.
322		for i := range l.segs {
323			if l.segs[i].hasCommits {
324				l.segDirty[l.segs[i].file] = true
325			}
326		}
327		for s := range l.index {
328			if g, ok := oldGenBySeq[s]; ok {
329				ref := l.index[s]
330				ref.gen = g
331				l.index[s] = ref
332			}
333		}
334		// Generations are an in-process monotonic counter; resume after the
335		// highest generation ever handed out so new commits never collide
336		// with a pre-truncation snapshot.
337		l.gen = oldGen
338		for s, recs := range live {
339			l.staged[s] = recs
340			if id := liveIDs[s]; id != "" {
341				l.stagedID[s] = id
342				// A staged keyed batch survives the truncation; its key
343				// must keep resolving to its reserved sequence for retries.
344				l.ids[id] = s
345			}
346			if s >= l.nextSeq {
347				l.nextSeq = s + 1
348			}
349		}
350	
351		// 5) Replace the sidecar with a snapshot of the retained segments
352		// and reopen the live append handle. A failure here does not lose
353		// data: the retained files are the source of truth and a stale or
354		// missing sidecar is rebuilt on the next open. The process keeps
355		// serving from the in-memory view just installed.
356		if l.idxFile != nil {
357			l.idxFile.Close()
358			l.idxFile = nil
359		}
360		if err := l.writeIndexSnapshot(p); err != nil && firstErr == nil {
361			firstErr = err
362		}
363		if err := l.openIndex(); err != nil && firstErr == nil {
364			firstErr = err
365		}
366		if firstErr != nil {
367			return len(deleted), fmt.Errorf("%w: %v", ErrRetentionFailed, firstErr)
368		}
369		return len(deleted), nil
370	}
371	
372	// listSegmentNumbers returns the numeric names of the *.seg files in
373	// dir, sorted ascending.
374	func listSegmentNumbers(dir string) ([]int, error) {
375		entries, err := os.ReadDir(dir)
376		if err != nil {
377			return nil, err
378		}
379		var nums []int
380		for _, e := range entries {
381			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
382				continue
383			}
384			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
385			if err != nil {
386				continue
387			}
388			nums = append(nums, n)
389		}
390		sort.Ints(nums)
391		return nums, nil
392	}
